const input = $input.first().json.body || $input.first().json;

const nome = (input.nome || input.name || 'Paciente').trim();
const email = (input.email || '').trim().toLowerCase();
let rawPhone = (input.whatsapp || input.telefone || input.phone || '').replace(/\D/g, '');

if (!rawPhone.startsWith('55') && rawPhone.length >= 10) {
  rawPhone = '55' + rawPhone;
}
const localPhone = rawPhone.startsWith('55') ? rawPhone.slice(2) : rawPhone;

const dataHoraIso = input.dataHora || input.dateTime || new Date().toISOString();
let dataFormatada = dataHoraIso;
try {
  const d = new Date(dataHoraIso);
  dataFormatada = d.toLocaleDateString('pt-BR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'America/Sao_Paulo'
  });
} catch (e) {}

const nameParts = nome.split(/\s+/);
const firstName = nameParts[0];
const lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : '';

return [{
  json: {
    nome,
    firstName,
    lastName,
    email,
    rawPhone,
    localPhone,
    dataHoraIso,
    dataFormatada,
    modalidade: input.modalidade || 'PRESENCIAL',
    motivo: input.motivo || 'Consulta médica geral'
  }
}];

const dados = $('2. Formatar Dados').first().json;
const existingPeople = $input.first().json?.data?.people || [];

const normalizedTarget = dados.rawPhone.replace(/\D/g, '');
const targetWithoutDdi = dados.localPhone.replace(/\D/g, '');

let found = null;
for (const p of existingPeople) {
  const w = (p.whatsapp?.primaryPhoneNumber || '').replace(/\D/g, '');
  const ph = (p.phones?.primaryPhoneNumber || '').replace(/\D/g, '');
  const em = (p.emails?.primaryEmail || '').toLowerCase();

  if (
    (w && (w === normalizedTarget || w === targetWithoutDdi)) ||
    (ph && (ph === normalizedTarget || ph === targetWithoutDdi)) ||
    (dados.email && em === dados.email)
  ) {
    found = p;
    break;
  }
}

return [{
  json: {
    ...dados,
    patientExists: !!found,
    patientId: found ? found.id : null
  }
}];

